DROP TABLE IF EXISTS `kind`;
CREATE TABLE `kind` (
  `token` varchar(64) NOT NULL,
  `origin` varchar(16) NOT NULL DEFAULT 'declared',
  PRIMARY KEY (`token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO `kind` (`token`,`origin`) VALUES ('bot','shipped'), ('challenge','shipped'), ('decision','shipped'), ('document','shipped'), ('event','shipped'), ('list','shipped'), ('machine','shipped'), ('org','shipped'), ('person','shipped'), ('pet','shipped'), ('place','shipped'), ('project','shipped'), ('promise','shipped'), ('rhythm','shipped'), ('role','shipped'), ('session','shipped'), ('thing','shipped'), ('thread','shipped'), ('topic','shipped'), ('view','shipped'), ('voucher','shipped'), ('work','shipped');
DROP TABLE IF EXISTS `mailbox`;
CREATE TABLE `mailbox` (
  `name` varchar(191) NOT NULL,
  `owner` varchar(191) NOT NULL,
  PRIMARY KEY (`name`),
  KEY `by_owner` (`owner`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO `mailbox` (`name`,`owner`) VALUES ('assistant','bot:assistant'), ('upgrade-fixture-chatterer','bot:upgrade-fixture-chatterer'), ('upgrade-fixture-heavy','bot:upgrade-fixture-heavy'), ('upgrade-fixture-lead','bot:upgrade-fixture-lead'), ('upgrade-fixture-parted','bot:upgrade-fixture-parted'), ('upgrade-fixture-taken','bot:upgrade-fixture-taken'), ('upgrade-fixture-trail','bot:upgrade-fixture-trail'), ('upgrade-fixture-wrapper','bot:upgrade-fixture-wrapper');
DROP TABLE IF EXISTS `merge_event`;
CREATE TABLE `merge_event` (
  `merge_no` bigint NOT NULL,
  `ordinal` bigint NOT NULL,
  `folded` varchar(191) NOT NULL,
  `survivor` varchar(191) NOT NULL,
  `merged_at` varchar(40) NOT NULL,
  `session` varchar(64),
  `folded_id` varchar(64),
  `survivor_id` varchar(64),
  PRIMARY KEY (`merge_no`,`ordinal`),
